var ICS_FREQ = { daily:'DAILY', weekly:'WEEKLY', monthly:'MONTHLY', yearly:'YEARLY', day:'DAILY', week:'WEEKLY', month:'MONTHLY', year:'YEARLY' };

function p2(n){ return (n < 10 ? '0' : '') + n; }

function escapeText(s){
  return String(s == null ? '' : s)
    .replace(/\\/g, '\\\\')
    .replace(/;/g, '\\;')
    .replace(/,/g, '\\,')
    .replace(/\r?\n/g, '\\n');
}

function hashHex(s){
