  if (!events.length) issues.push({ level:'bad', msg:'没有任何事件' });
  for (var i = 0; i < events.length; i++){
    var e = events[i];
    if (!e.title) issues.push({ level:'bad', msg:'第 ' + (i + 1) + ' 个事件缺少标题' });
    if (!e.start) issues.push({ level:'bad', msg:'事件「' + (e.title || '未命名') + '」缺少 start 时间' });
    else {
      var s = parseDateTz(e.start), en = e.end ? parseDateTz(e.end) : null;
      if (s && en && s.kind === en.kind && en.ms <= s.ms) issues.push({ level:'bad', msg:'事件「' + e.title + '」的结束时间不晚于开始时间' });
    }
    if (e.repeat && !ICS_FREQ[String(e.repeat).toLowerCase()]) issues.push({ level:'warn', msg:'事件「' + e.title + '」的 repeat 取值不被识别' });
  }
  var conflicts = detectConflicts(events);
  for (var c = 0; c < conflicts.length; c++){
    issues.push({ level:'warn', msg:'时间冲突：「' + conflicts[c].titleA + '」与「' + conflicts[c].titleB + '」重叠' });
